      SUBROUTINE TWIT3CCC     DETERMINES CONTRIBUTION OF THIRD-ORDER TRANSFER MATRIX TOC     TRANSFORM OF PARTIALS OF BEAM CENTROIDCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM7D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'U.CIN'CC     TRANSFORM DERIVATIVE OF REFERENCE TRAJECTORY DISPLACEMENTC      DO 20 J = 1, 5      SS = 0.0      IND = 0      DO 10 L3 = 1, 6      DO 10 L2 = 1, L3      DO 10 L1 = 1, L2      IND = IND + 1      SS = SS + U(J,IND)*(CO(L1)*CO(L2)*COV(L3,NV2)     1                  + CO(L1)*COV(L2,NV2)*CO(L3)     2                  + COV(L1,NV2)*CO(L2)*CO(L3))   10 CONTINUE      COT(J) = COT(J) + SS   20 CONTINUEC  400 RETURN      END